TRUNCATE TABLE IF EXISTS REF.PAYERS;
INSERT INTO REF.PAYERS (PAYER_ID, NAME, SHORT_NAME, REVENUE_SHARE_PCT, TARGET_DSO_DAYS, PAYER_TYPE)
SELECT f.value:PAYER_ID::STRING AS PAYER_ID,
       f.value:NAME::STRING AS NAME,
       f.value:SHORT_NAME::STRING AS SHORT_NAME,
       f.value:REVENUE_SHARE_PCT::FLOAT AS REVENUE_SHARE_PCT,
