TRUNCATE TABLE IF EXISTS REF.OR_PLAN_TOMORROW;
INSERT INTO REF.OR_PLAN_TOMORROW (SEQ, ROOM, PROCEDURE_NAME, SURGEON, SURGEON_ESTIMATE_MIN, MODEL_P50_MIN, MODEL_P90_MIN, ASA, CANCEL_RISK)
SELECT f.value:SEQ::INT AS SEQ,
       f.value:ROOM::STRING AS ROOM,
       f.value:PROCEDURE_NAME::STRING AS PROCEDURE_NAME,
       f.value:SURGEON::STRING AS SURGEON,
       f.value:SURGEON_ESTIMATE_MIN::INT AS SURGEON_ESTIMATE_MIN,
       f.value:MODEL_P50_MIN::INT AS MODEL_P50_MIN,
       f.value:MODEL_P90_MIN::INT AS MODEL_P90_MIN,
       f.value:ASA::INT AS ASA,
       f.value:CANCEL_RISK::FLOAT AS CANCEL_RISK
