TRUNCATE TABLE IF EXISTS REF.OR_PREOP;
INSERT INTO REF.OR_PREOP (PATIENT_NAME, AGE, PROCEDURE_NAME, SLOT, PAYER, CHECKLIST, CANCEL_RISK, ICU_RISK, COMPLICATION_RISK, EXPECTED_LOS_DAYS)
