TRUNCATE TABLE IF EXISTS REF.MODEL_CATALOG;
INSERT INTO REF.MODEL_CATALOG (MODEL_ID, NAME, USE_CASE, ALGORITHM, STATUS, METRIC_NAME, METRIC_VALUE, PREDICTIONS_PER_DAY, DESCRIPTION, DETAILS, FEATURE_IMPORTANCE, LINEAGE)
SELECT f.value:MODEL_ID::STRING AS MODEL_ID,
       f.value:NAME::STRING AS NAME,
       f.value:USE_CASE::STRING AS USE_CASE,
       f.value:ALGORITHM::STRING AS ALGORITHM,
       f.value:STATUS::STRING AS STATUS,
       f.value:METRIC_NAME::STRING AS METRIC_NAME,
       f.value:METRIC_VALUE::STRING AS METRIC_VALUE,
       f.value:PREDICTIONS_PER_DAY::STRING AS PREDICTIONS_PER_DAY,
       f.value:DESCRIPTION::STRING AS DESCRIPTION,
       f.value:DETAILS AS DETAILS,
       f.value:FEATURE_IMPORTANCE AS FEATURE_IMPORTANCE,
       f.value:LINEAGE AS LINEAGE
FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[{"MODEL_ID":"M01","NAME":"Afluência à urgência","USE_CASE":"Episódios por hora, a 72 h","ALGORITHM":"Snowflake Forecast","STATUS":"Em produção","METRIC_NAME":"Precisão (1 − MAPE)","METRIC_VALUE":"91,8%","PREDICTIONS_PER_DAY":"2 160","DESCRIPTION":"Prevê episódios de urgência por hora e unidade, para planear escalas e abrir áreas de observação.","DETAILS":[["Treino","Semanal · domingo 02:00"],["Histórico","5 anos · 9,2 M episódios"],["Variáveis externas","IPMA, feriados, gripe (DGS)"],["Decisão servida","Escalas de urgência"],["Controlo humano","Aprovação do chefe de equipa"]],"FEATURE_IMPORTANCE":[["Hora do dia",0.29],["Dia da semana",0.21],["Incidência gripal",0.16],["Temperatura",0.12],["Feriado/véspera",0.11],["Eventos locais",0.06]],"LINEAGE":["Processo clínico · episódios","Dados meteorológicos","Feature Store","Modelo de previsão","Escalas aprovadas"]},{"MODEL_ID":"M02","NAME":"Faltas a consultas","USE_CASE":"Probabilidade de no-show","ALGORITHM":"XGBoost · Snowpark ML","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,87","PREDICTIONS_PER_DAY":"31 400","DESCRIPTION":"Identifica consultas com maior risco de falta para lembretes direcionados e overbooking controlado.","DETAILS":[["Treino","Diário · 03:00"],["Histórico","3 anos · 21 M marcações"],["Ação automática","Lembrete MY LUZ / SMS"],["Impacto medido","−1,4 p.p. na taxa de faltas"],["Controlo humano","Overbooking requer validação"]],"FEATURE_IMPORTANCE":[["Faltas anteriores",0.33],["Antecedência da marcação",0.19],["Distância ao hospital",0.14],["Confirmação na app",0.13],["Hora da consulta",0.11],["Tipo de financiador",0.1]],"LINEAGE":["Agenda de marcações","Eventos app MY LUZ","Feature Store","Modelo no-show","Lembretes enviados"]},{"MODEL_ID":"M03","NAME":"Risco de rejeição","USE_CASE":"Glosa antes do envio","ALGORITHM":"LightGBM · Snowpark ML","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,91","PREDICTIONS_PER_DAY":"18 900","DESCRIPTION":"Antecipa episódios que a entidade financiadora irá rejeitar e indica o motivo provável.","DETAILS":[["Treino","Semanal"],["Histórico","4 anos · 14 M faturas"],["Receita recuperada","4,2 M€/ano (estimativa)"],["Decisão servida","Revisão pré-faturação"],["Controlo humano","Correção por faturação"]],"FEATURE_IMPORTANCE":[["Autorização prévia",0.36],["Combinação ato/diagnóstico",0.22],["Entidade e plano",0.17],["Médico requisitante",0.1],["Valor do episódio",0.09],["Urgência vs. programado",0.06]],"LINEAGE":["Faturação e convenções","Respostas das seguradoras","Cortex AI · classificação","Modelo de glosa","Fila de revisão"]},{"MODEL_ID":"M04","NAME":"Readmissão a 30 dias","USE_CASE":"Risco após alta","ALGORITHM":"Regressão logística","STATUS":"Drift detetado","METRIC_NAME":"AUC","METRIC_VALUE":"0,79","PREDICTIONS_PER_DAY":"1 250","DESCRIPTION":"Classifica doentes com alta pelo risco de readmissão. Drift detetado após mudança de protocolo em Cardiologia; retreino agendado.","DETAILS":[["Treino","Mensal"],["Último retreino","há 41 dias"],["Drift (PSI)","0,23 · acima do limiar"],["Decisão servida","Chamada de follow-up"],["Controlo humano","Validação clínica obrigatória"]],"FEATURE_IMPORTANCE":[["N.º internamentos 12 m",0.27],["Índice de Charlson",0.23],["Demora média",0.15],["Polimedicação",0.14],["Idade",0.11],["Apoio social",0.1]],"LINEAGE":["Processo clínico","Notas de alta · Cortex AI","Feature Store","Modelo de readmissão","Equipa de follow-up"]},{"MODEL_ID":"M05","NAME":"Duração cirúrgica","USE_CASE":"Minutos por cirurgia","ALGORITHM":"Random Forest","STATUS":"Em produção","METRIC_NAME":"Erro médio","METRIC_VALUE":"11 min","PREDICTIONS_PER_DAY":"640","DESCRIPTION":"Estima a duração de cada cirurgia para construir planos operatórios mais realistas.","DETAILS":[["Treino","Semanal"],["Histórico","420 mil cirurgias"],["Impacto","+9% utilização de salas"],["Decisão servida","Plano operatório"],["Controlo humano","Validação do cirurgião"]],"FEATURE_IMPORTANCE":[["Procedimento",0.41],["Cirurgião",0.2],["ASA",0.13],["IMC",0.1],["Hora de início",0.09],["Anestesia",0.07]],"LINEAGE":["Registo de bloco","Processo clínico","Feature Store","Modelo de duração","Plano operatório"]},{"MODEL_ID":"M06","NAME":"Risco de queda","USE_CASE":"Residentes, a 7 dias","ALGORITHM":"Gradient Boosting","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,84","PREDICTIONS_PER_DAY":"1 284","DESCRIPTION":"Identifica residentes e utentes com risco aumentado de queda para planos preventivos.","DETAILS":[["Treino","Quinzenal"],["Dados de sensores","Sim · quartos equipados"],["Impacto","−22% quedas com lesão"],["Decisão servida","Plano preventivo"],["Controlo humano","Enfermeiro responsável"]],"FEATURE_IMPORTANCE":[["Quedas anteriores",0.31],["Psicofármacos",0.24],["Levantes noturnos",0.17],["Tinetti",0.13],["Idade",0.08],["Infeção recente",0.07]],"LINEAGE":["Registos de enfermagem","Sensores IoT","Feature Store","Modelo de queda","Planos preventivos"]},{"MODEL_ID":"M07","NAME":"Procura de medicamentos","USE_CASE":"Consumo a 14 dias","ALGORITHM":"Snowflake Forecast","STATUS":"Em produção","METRIC_NAME":"Precisão","METRIC_VALUE":"93,1%","PREDICTIONS_PER_DAY":"48 000","DESCRIPTION":"Prevê consumo por artigo e unidade para evitar ruturas e reduzir stock imobilizado.","DETAILS":[["Treino","Diário"],["Artigos","12 400"],["Ruturas evitadas","27 nos últimos 30 dias"],["Decisão servida","Encomendas no ERP"],["Controlo humano","Aprovação de compras"]],"FEATURE_IMPORTANCE":[["Histórico de consumo",0.38],["Plano operatório",0.22],["Sazonalidade",0.17],["Ocupação prevista",0.13],["Prazo do fornecedor",0.1]],"LINEAGE":["ERP · stocks e compras","Plano operatório","Feature Store","Previsão de procura","Pedidos de compra"]},{"MODEL_ID":"M08","NAME":"Próxima melhor ação","USE_CASE":"Recomendação por doente","ALGORITHM":"Cortex AI + regras clínicas","STATUS":"Piloto","METRIC_NAME":"Aceitação","METRIC_VALUE":"34%","PREDICTIONS_PER_DAY":"22 000","DESCRIPTION":"Combina guidelines clínicas, histórico e preferências para sugerir o próximo passo de cuidados na app MY LUZ.","DETAILS":[["Fase","Piloto · 3 unidades"],["Conversão em marcação","12%"],["Canais","App MY LUZ, email"],["Decisão servida","Campanhas de seguimento"],["Controlo humano","Revisão clínica das regras"]],"FEATURE_IMPORTANCE":[["Seguimento em atraso",0.34],["Rastreios elegíveis",0.25],["Cobertura do seguro",0.16],["Engagement na app",0.15],["Preferência de canal",0.1]],"LINEAGE":["Doente 360°","Guidelines clínicas · Cortex Search","Cortex AI","Recomendação","Notificação MY LUZ"]},{"MODEL_ID":"M09","NAME":"Alerta precoce de sépsis","USE_CASE":"Risco em tempo real","ALGORITHM":"Gradient Boosting + LLM","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,89","PREDICTIONS_PER_DAY":"182 400","DESCRIPTION":"Combina sinais vitais com texto livre das notas de enfermagem (Cortex AI) para alertar suspeita de sépsis.","DETAILS":[["Atualização","A cada nova medição"],["Fonte de texto","AI_EXTRACT sobre notas"],["Agente","Vigilância de sépsis"],["Decisão servida","Avaliação médica urgente"],["Controlo humano","Decisão sempre do médico"]],"FEATURE_IMPORTANCE":[["Frequência cardíaca",0.24],["Temperatura",0.19],["Estado de consciência (texto)",0.17],["Lactato prévio",0.14],["Tensão arterial",0.14],["Idade e comorbilidades",0.12]],"LINEAGE":["Monitores de sinais vitais","Notas · Cortex AI","Feature Store (streaming)","Modelo de sépsis","Alerta à equipa"]},{"MODEL_ID":"M10","NAME":"Previsão de alta","USE_CASE":"Alta nas próximas 24 h","ALGORITHM":"XGBoost · Snowpark ML","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,86","PREDICTIONS_PER_DAY":"1 640","DESCRIPTION":"Estima a probabilidade de alta de cada doente internado para planear camas e cirurgias.","DETAILS":[["Treino","Semanal"],["Agente","Gestor de camas"],["Impacto","−22% cancelamentos por falta de cama"],["Decisão servida","Plano de altas"],["Controlo humano","Médico assistente"]],"FEATURE_IMPORTANCE":[["Dias de internamento vs. esperado",0.29],["Tendência de análises",0.2],["Medicação EV ativa",0.18],["Notas \"alta prevista\"",0.15],["Dia da semana",0.1],["Apoio social",0.08]],"LINEAGE":["Internamentos","Análises e prescrições","Feature Store","Modelo de alta","Gestão de camas"]},{"MODEL_ID":"M11","NAME":"Correspondência para ensaios","USE_CASE":"Elegibilidade de doentes","ALGORITHM":"Embeddings + regras (Cortex)","STATUS":"Piloto","METRIC_NAME":"Precisão","METRIC_VALUE":"0,83","PREDICTIONS_PER_DAY":"9 800","DESCRIPTION":"Compara critérios de inclusão dos protocolos com o processo clínico estruturado e não estruturado.","DETAILS":[["Protocolos indexados","64"],["Agente","Recrutamento para ensaios"],["Consentimento","Verificado antes da sugestão"],["Decisão servida","Convite do investigador"],["Controlo humano","Investigador principal"]],"FEATURE_IMPORTANCE":[["Diagnóstico e estadio",0.31],["Biomarcadores",0.24],["Função renal e hepática",0.16],["Terapêuticas prévias",0.15],["Idade",0.08],["Distância ao centro",0.06]],"LINEAGE":["Protocolos · Cortex Search","Processo clínico","Embeddings","Modelo de correspondência","Portal do investigador"]},{"MODEL_ID":"M12","NAME":"Risco de saída de colaboradores","USE_CASE":"Saída a 12 meses","ALGORITHM":"Survival (Cox) · Snowpark ML","STATUS":"Em produção","METRIC_NAME":"C-index","METRIC_VALUE":"0,78","PREDICTIONS_PER_DAY":"14 012","DESCRIPTION":"Estima o risco de saída por colaborador para ações de retenção pela chefia direta.","DETAILS":[["Treino","Mensal"],["Visibilidade","Chefia direta e RH (row access policy)"],["Variáveis excluídas","Género, idade, nacionalidade"],["Decisão servida","Plano de retenção"],["Controlo humano","Sempre"]],"FEATURE_IMPORTANCE":[["Horas extra (3 meses)",0.27],["Noites e fins de semana",0.21],["Pedidos recusados",0.16],["Tempo sem progressão",0.15],["Distância casa-trabalho",0.11],["Tipo de contrato",0.1]],"LINEAGE":["RH · contratos e escalas","Avaliações","Feature Store","Modelo de saída","Colaborador 360°"]},{"MODEL_ID":"M13","NAME":"Demora média esperada","USE_CASE":"Dias de internamento","ALGORITHM":"LightGBM","STATUS":"Em produção","METRIC_NAME":"Erro médio","METRIC_VALUE":"0,9 dias","PREDICTIONS_PER_DAY":"1 250","DESCRIPTION":"Estima a demora esperada à admissão por GDH e perfil do doente, para comparar com o real.","DETAILS":[["Treino","Mensal"],["Agrupamento","GDH + comorbilidades"],["Uso","Benchmark entre hospitais"],["Decisão servida","Gestão de casos"],["Controlo humano","Gestor de casos"]],"FEATURE_IMPORTANCE":[["GDH",0.34],["Índice de Charlson",0.22],["Idade",0.14],["Origem (urgência/programado)",0.13],["Hospital",0.1],["Apoio social",0.07]],"LINEAGE":["Episódios","Codificação GDH","Feature Store","Modelo de demora","Painel de operações"]},{"MODEL_ID":"M14","NAME":"Triagem de RX de tórax","USE_CASE":"Prioridade de leitura","ALGORITHM":"Visão computacional (parceiro)","STATUS":"Piloto","METRIC_NAME":"Sensibilidade","METRIC_VALUE":"0,94","PREDICTIONS_PER_DAY":"1 180","DESCRIPTION":"Ordena a lista de leitura do radiologista, colocando primeiro os exames com achados urgentes. Piloto 37 do programa de inovação.","DETAILS":[["Origem","Startup do programa de 50 pilotos"],["Execução","Snowpark Container Services"],["Impacto","Achados urgentes lidos 38 min mais cedo"],["Decisão servida","Ordem de leitura"],["Controlo humano","Relatório sempre do radiologista"]],"FEATURE_IMPORTANCE":[["Opacidades",0.3],["Derrame pleural",0.22],["Pneumotórax",0.2],["Cardiomegalia",0.15],["Qualidade da imagem",0.13]],"LINEAGE":["PACS · imagens","Container Services","Modelo de visão","Fila de leitura","Radiologista"]},{"MODEL_ID":"M15","NAME":"Abandono de clientes","USE_CASE":"Risco de mudar de prestador","ALGORITHM":"XGBoost","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,81","PREDICTIONS_PER_DAY":"1,6 M","DESCRIPTION":"Identifica clientes com risco de procurar outro grupo, para ações de fidelização (LUZ ON PRIME, MY LUZ).","DETAILS":[["Treino","Mensal"],["Universo","Utilizadores MY LUZ"],["Impacto","+4 p.p. de retenção em campanhas"],["Decisão servida","Campanhas de fidelização"],["Controlo humano","Equipa de marketing"]],"FEATURE_IMPORTANCE":[["Reclamações recentes",0.26],["Plafond do seguro esgotado",0.21],["Tempo de espera vivido",0.18],["Pesquisa de outros prestadores",0.14],["Uso da app",0.12],["NPS",0.09]],"LINEAGE":["Doente 360°","Eventos MY LUZ","Feature Store","Modelo de abandono","Campanhas"]},{"MODEL_ID":"M16","NAME":"Anomalias de faturação","USE_CASE":"Padrões suspeitos","ALGORITHM":"Isolation Forest","STATUS":"Em produção","METRIC_NAME":"Precisão","METRIC_VALUE":"0,72","PREDICTIONS_PER_DAY":"18 900","DESCRIPTION":"Deteta atos e faturas anómalas, partilhando padrões agregados com a seguradora via Clean Room.","DETAILS":[["Treino","Semanal"],["Partilha","Clean Room com a Fidelidade"],["Detetado no ano","0,6 M€"],["Decisão servida","Auditoria"],["Controlo humano","Auditor interno"]],"FEATURE_IMPORTANCE":[["Frequência de atos por médico",0.29],["Combinações raras de atos",0.25],["Horário do registo",0.16],["Valor vs. mediana",0.16],["Correções posteriores",0.14]],"LINEAGE":["Faturação","Clean Room Fidelidade","Feature Store","Modelo de anomalias","Auditoria"]},{"MODEL_ID":"M17","NAME":"Procura nas clínicas","USE_CASE":"Consultas por clínica e dia","ALGORITHM":"Snowflake Forecast (multi-série)","STATUS":"Em produção","METRIC_NAME":"Precisão","METRIC_VALUE":"90,4%","PREDICTIONS_PER_DAY":"24 séries","DESCRIPTION":"Prevê consultas por clínica e especialidade para abrir agendas e alocar médicos.","DETAILS":[["Treino","Semanal"],["Séries","24 clínicas × 18 especialidades"],["Sinais externos","Feriados, escolas, IPMA"],["Decisão servida","Abertura de agendas"],["Controlo humano","Diretor da clínica"]],"FEATURE_IMPORTANCE":[["Sazonalidade semanal",0.32],["Histórico de marcações",0.27],["Calendário escolar",0.14],["Feriados",0.13],["Temperatura",0.08],["Campanhas MY LUZ",0.06]],"LINEAGE":["Agendas das clínicas","Sinais externos","Feature Store","Previsão de procura","Abertura de agendas"]},{"MODEL_ID":"M18","NAME":"Risco de cancelamento cirúrgico","USE_CASE":"Cirurgia não realizada","ALGORITHM":"XGBoost · Snowpark ML","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,84","PREDICTIONS_PER_DAY":"1 640","DESCRIPTION":"Prevê, 48 h antes, a probabilidade de uma cirurgia programada não se realizar, para o agente de preparação atuar a tempo.","DETAILS":[["Treino","Semanal"],["Agentes","Preparação pré-operatória · Otimizador do bloco"],["Impacto","−38% de cancelamentos por doente não apto"],["Decisão servida","Contacto e preparação do doente"],["Controlo humano","Enfermagem do bloco"]],"FEATURE_IMPORTANCE":[["Checklist pré-operatório incompleto",0.31],["Instruções de jejum não lidas",0.19],["Cancelamentos anteriores",0.16],["Autorização do seguro pendente",0.14],["ASA e comorbilidades",0.12],["Distância ao hospital",0.08]],"LINEAGE":["Plano operatório","Processo clínico e app MY LUZ","Feature Store","Modelo de cancelamento","Agente de preparação"]},{"MODEL_ID":"M19","NAME":"Necessidade de UCI pós-operatória","USE_CASE":"Cama de UCI após cirurgia","ALGORITHM":"Regressão logística","STATUS":"Em produção","METRIC_NAME":"AUC","METRIC_VALUE":"0,88","PREDICTIONS_PER_DAY":"1 640","DESCRIPTION":"Estima se o doente vai precisar de cuidados intensivos depois da cirurgia, para reservar a cama no dia anterior.","DETAILS":[["Treino","Mensal"],["Agente","Otimizador do plano operatório"],["Impacto","Cirurgias adiadas por falta de UCI −46%"],["Decisão servida","Reserva de cama de UCI"],["Controlo humano","Anestesiologista"]],"FEATURE_IMPORTANCE":[["Tipo de cirurgia",0.34],["ASA",0.22],["Idade",0.14],["Função renal",0.11],["Insuficiência cardíaca",0.1],["Duração prevista",0.09]],"LINEAGE":["Plano operatório","Avaliação anestésica","Feature Store","Modelo de UCI","Gestão de camas"]}]$$))) f;


-- --------------------------------------------------------------------------------------
-- KPI dictionary (certified definitions)
-- --------------------------------------------------------------------------------------

TRUNCATE TABLE IF EXISTS REF.KPI_DICTIONARY;
INSERT INTO REF.KPI_DICTIONARY (KPI_NAME, DOMAIN, DEFINITION, FORMULA, OWNER, SOURCES, SEMANTIC_VIEW, REFRESH, QUALITY_PCT, CERTIFIED)
SELECT f.value:KPI_NAME::STRING AS KPI_NAME,
       f.value:DOMAIN::STRING AS DOMAIN,
       f.value:DEFINITION::STRING AS DEFINITION,
       f.value:FORMULA::STRING AS FORMULA,
       f.value:OWNER::STRING AS OWNER,
       f.value:SOURCES AS SOURCES,
       f.value:SEMANTIC_VIEW::STRING AS SEMANTIC_VIEW,
       f.value:REFRESH::STRING AS REFRESH,
       f.value:QUALITY_PCT::FLOAT AS QUALITY_PCT,
       f.value:CERTIFIED::BOOLEAN AS CERTIFIED
FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[{"KPI_NAME":"Ocupação de internamento","DOMAIN":"Operações","DEFINITION":"Percentagem de camas de internamento ocupadas à meia-noite.","FORMULA":"SUM(camas_ocupadas) / SUM(camas_disponiveis)","OWNER":"Direção de Operações","SOURCES":["Processo clínico · ADT","OPERACOES.OCUPACAO_DIARIA"],"SEMANTIC_VIEW":"SV_OPERACOES","REFRESH":"A cada 15 min","QUALITY_PCT":99.6,"CERTIFIED":true},{"KPI_NAME":"Ocupação de camas","DOMAIN":"Operações","DEFINITION":"Igual a \"Ocupação de internamento\", calculada por hospital e serviço.","FORMULA":"SUM(camas_ocupadas) / SUM(camas_disponiveis)","OWNER":"Direção de Operações","SOURCES":["Processo clínico · ADT","OPERACOES.OCUPACAO_DIARIA"],"SEMANTIC_VIEW":"SV_OPERACOES","REFRESH":"A cada 15 min","QUALITY_PCT":99.6,"CERTIFIED":true},{"KPI_NAME":"Demora média","DOMAIN":"Operações","DEFINITION":"Média de dias entre admissão e alta, nos episódios de internamento com alta no período.","FORMULA":"AVG(DATEDIFF(day, data_admissao, data_alta))","OWNER":"Direção Clínica","SOURCES":["Processo clínico · episódios","CLINICO.EPISODIOS_INTERNAMENTO"],"SEMANTIC_VIEW":"SV_INTERNAMENTOS","REFRESH":"Diária · 05:00","QUALITY_PCT":99.2,"CERTIFIED":true},{"KPI_NAME":"Espera média na urgência","DOMAIN":"Operações","DEFINITION":"Minutos entre a triagem e a primeira observação médica.","FORMULA":"AVG(DATEDIFF(minute, hora_triagem, hora_1a_observacao))","OWNER":"Direção de Urgência","SOURCES":["Sistema de urgência","URGENCIA.EPISODIOS"],"SEMANTIC_VIEW":"SV_URGENCIA","REFRESH":"A cada 5 min","QUALITY_PCT":98.9,"CERTIFIED":true},{"KPI_NAME":"Episódios de urgência hoje","DOMAIN":"Operações","DEFINITION":"Número de episódios de urgência admitidos desde as 00:00.","FORMULA":"COUNT(episodio_id)","OWNER":"Direção de Urgência","SOURCES":["Sistema de urgência","URGENCIA.EPISODIOS"],"SEMANTIC_VIEW":"SV_URGENCIA","REFRESH":"A cada 5 min","QUALITY_PCT":99.8,"CERTIFIED":true},{"KPI_NAME":"Utilização do bloco","DOMAIN":"Operações","DEFINITION":"Minutos de cirurgia realizados sobre minutos de bloco atribuídos.","FORMULA":"SUM(min_cirurgia) / SUM(min_atribuidos)","OWNER":"Direção do Bloco Operatório","SOURCES":["Registo de bloco","BLOCO.SESSOES"],"SEMANTIC_VIEW":"SV_BLOCO","REFRESH":"Diária · 05:00","QUALITY_PCT":98.4,"CERTIFIED":true},{"KPI_NAME":"Cirurgias canceladas","DOMAIN":"Operações","DEFINITION":"Cirurgias programadas canceladas no próprio dia, sobre o total programado.","FORMULA":"COUNT_IF(cancelada_mesmo_dia) / COUNT(*)","OWNER":"Direção do Bloco Operatório","SOURCES":["Registo de bloco","BLOCO.CIRURGIAS"],"SEMANTIC_VIEW":"SV_BLOCO","REFRESH":"Diária · 05:00","QUALITY_PCT":97.9,"CERTIFIED":true},{"KPI_NAME":"Taxa de faltas","DOMAIN":"Ambulatório","DEFINITION":"Consultas marcadas a que o doente não compareceu, sem desmarcação prévia.","FORMULA":"COUNT_IF(estado = 'falta') / COUNT(*)","OWNER":"Direção de Ambulatório","SOURCES":["Agendas","AMBULATORIO.MARCACOES"],"SEMANTIC_VIEW":"SV_AMBULATORIO","REFRESH":"Diária · 05:00","QUALITY_PCT":99.4,"CERTIFIED":true},{"KPI_NAME":"Tempo até 1.ª consulta","DOMAIN":"Ambulatório","DEFINITION":"Dias entre o pedido e a data da primeira consulta da especialidade.","FORMULA":"MEDIAN(DATEDIFF(day, data_pedido, data_consulta))","OWNER":"Direção de Ambulatório","SOURCES":["Agendas","AMBULATORIO.MARCACOES"],"SEMANTIC_VIEW":"SV_AMBULATORIO","REFRESH":"Diária · 05:00","QUALITY_PCT":98.7,"CERTIFIED":true},{"KPI_NAME":"Teleconsultas","DOMAIN":"Ambulatório","DEFINITION":"Teleconsultas (Hospital da Luz Digital e LUZ 24) sobre o total de consultas.","FORMULA":"COUNT_IF(tipo = 'tele') / COUNT(*)","OWNER":"Direção Digital","SOURCES":["Agendas","Plataforma de videoconsulta"],"SEMANTIC_VIEW":"SV_AMBULATORIO","REFRESH":"Diária · 05:00","QUALITY_PCT":99.1,"CERTIFIED":true},{"KPI_NAME":"Prazo médio de recebimento","DOMAIN":"Finanças","DEFINITION":"Dias médios entre a emissão da fatura e o recebimento, ponderados pelo valor.","FORMULA":"SUM(valor * dias_ate_pagamento) / SUM(valor)","OWNER":"Direção Financeira","SOURCES":["ERP · contas a receber","FINANCAS.RECEBIMENTOS"],"SEMANTIC_VIEW":"SV_RECEITA","REFRESH":"Diária · 06:00","QUALITY_PCT":99.7,"CERTIFIED":true},{"KPI_NAME":"Taxa de rejeição","DOMAIN":"Finanças","DEFINITION":"Valor de faturas rejeitadas pela entidade sobre o valor faturado.","FORMULA":"SUM(valor_rejeitado) / SUM(valor_faturado)","OWNER":"Direção Financeira","SOURCES":["Faturação","RECEITA.FATURAS"],"SEMANTIC_VIEW":"SV_RECEITA","REFRESH":"Diária · 06:00","QUALITY_PCT":99.3,"CERTIFIED":true},{"KPI_NAME":"Margem operacional","DOMAIN":"Finanças","DEFINITION":"EBITDA sobre receita, por hospital ou ponderado por camas no grupo.","FORMULA":"(receita - custos_operacionais) / receita","OWNER":"Direção Financeira","SOURCES":["ERP · contabilidade analítica","FINANCAS.RESULTADOS"],"SEMANTIC_VIEW":"SV_FINANCAS","REFRESH":"Mensal · dia 3","QUALITY_PCT":99.9,"CERTIFIED":true},{"KPI_NAME":"Receita por episódio","DOMAIN":"Finanças","DEFINITION":"Receita faturada sobre o número de episódios com faturação no período.","FORMULA":"SUM(valor_faturado) / COUNT(DISTINCT episodio_id)","OWNER":"Direção Financeira","SOURCES":["Faturação","RECEITA.FATURAS"],"SEMANTIC_VIEW":"SV_RECEITA","REFRESH":"Diária · 06:00","QUALITY_PCT":99.3,"CERTIFIED":true},{"KPI_NAME":"Custo por episódio","DOMAIN":"Finanças","DEFINITION":"Custos diretos e indiretos alocados ao episódio pela contabilidade analítica.","FORMULA":"SUM(custo_alocado) / COUNT(DISTINCT episodio_id)","OWNER":"Direção Financeira","SOURCES":["ERP · contabilidade analítica","FINANCAS.CUSTOS_EPISODIO"],"SEMANTIC_VIEW":"SV_FINANCAS","REFRESH":"Mensal · dia 3","QUALITY_PCT":97.8,"CERTIFIED":false},{"KPI_NAME":"Readmissões a 30 dias","DOMAIN":"Qualidade","DEFINITION":"Internamentos não programados até 30 dias após uma alta, sobre o total de altas.","FORMULA":"COUNT(readmissao_30d) / COUNT(altas)","OWNER":"Gabinete de Qualidade","SOURCES":["Processo clínico · episódios","QUALIDADE.READMISSOES"],"SEMANTIC_VIEW":"SV_QUALIDADE","REFRESH":"Diária · 05:00","QUALITY_PCT":99,"CERTIFIED":true},{"KPI_NAME":"Infeção hospitalar (IACS)","DOMAIN":"Qualidade","DEFINITION":"Prevalência de infeções associadas aos cuidados de saúde no estudo de ponto.","FORMULA":"COUNT(doentes_com_IACS) / COUNT(doentes_internados)","OWNER":"Comissão de Controlo de Infeção","SOURCES":["Registo de IACS","QUALIDADE.IACS"],"SEMANTIC_VIEW":"SV_QUALIDADE","REFRESH":"Semanal","QUALITY_PCT":96.4,"CERTIFIED":true},{"KPI_NAME":"Índice de mortalidade (O/E)","DOMAIN":"Qualidade","DEFINITION":"Mortalidade observada sobre a esperada para o case-mix (ajustada ao risco).","FORMULA":"SUM(obitos) / SUM(prob_obito_esperada)","OWNER":"Gabinete de Qualidade","SOURCES":["Processo clínico","Modelo de risco ajustado"],"SEMANTIC_VIEW":"SV_QUALIDADE","REFRESH":"Mensal","QUALITY_PCT":98.1,"CERTIFIED":true},{"KPI_NAME":"Complicações cirúrgicas","DOMAIN":"Qualidade","DEFINITION":"Episódios cirúrgicos com pelo menos uma complicação registada até 30 dias.","FORMULA":"COUNT_IF(complicacao_30d) / COUNT(*)","OWNER":"Gabinete de Qualidade","SOURCES":["Registo de bloco","Notas clínicas · Cortex AI"],"SEMANTIC_VIEW":"SV_QUALIDADE","REFRESH":"Diária · 05:00","QUALITY_PCT":95.9,"CERTIFIED":false},{"KPI_NAME":"NPS","DOMAIN":"Experiência","DEFINITION":"Net Promoter Score dos inquéritos pós-episódio (promotores menos detratores).","FORMULA":"%(nota 9-10) - %(nota 0-6)","OWNER":"Direção de Experiência do Cliente","SOURCES":["App MY LUZ","Inquéritos SMS"],"SEMANTIC_VIEW":"SV_EXPERIENCIA","REFRESH":"Diária · 06:00","QUALITY_PCT":99.5,"CERTIFIED":true},{"KPI_NAME":"Absentismo","DOMAIN":"Pessoas","DEFINITION":"Horas de ausência não planeada sobre horas contratadas.","FORMULA":"SUM(horas_ausencia) / SUM(horas_contratadas)","OWNER":"Direção de Recursos Humanos","SOURCES":["Sistema de RH e assiduidade","RH.ASSIDUIDADE"],"SEMANTIC_VIEW":"SV_PESSOAS","REFRESH":"Diária · 04:00","QUALITY_PCT":99.2,"CERTIFIED":true},{"KPI_NAME":"Horas extra (mês)","DOMAIN":"Pessoas","DEFINITION":"Horas trabalhadas para além do horário contratado no mês corrente.","FORMULA":"SUM(horas_extra)","OWNER":"Direção de Recursos Humanos","SOURCES":["Sistema de RH e assiduidade","RH.ESCALAS"],"SEMANTIC_VIEW":"SV_PESSOAS","REFRESH":"Diária · 04:00","QUALITY_PCT":98.8,"CERTIFIED":true},{"KPI_NAME":"Profissionais por cama","DOMAIN":"Pessoas","DEFINITION":"Colaboradores (equivalente a tempo inteiro) por cama disponível.","FORMULA":"SUM(ETI) / SUM(camas)","OWNER":"Direção de Recursos Humanos","SOURCES":["Sistema de RH","OPERACOES.CAMAS"],"SEMANTIC_VIEW":"SV_PESSOAS","REFRESH":"Mensal","QUALITY_PCT":99.6,"CERTIFIED":true},{"KPI_NAME":"Receita acumulada 2026","DOMAIN":"Finanças","DEFINITION":"Receita reconhecida de janeiro até ao último fecho mensal.","FORMULA":"SUM(receita) WHERE ano = 2026","OWNER":"Direção Financeira","SOURCES":["ERP · contabilidade","FINANCAS.RESULTADOS"],"SEMANTIC_VIEW":"SV_FINANCAS","REFRESH":"Mensal · dia 3","QUALITY_PCT":99.9,"CERTIFIED":true}]$$))) f;


