TRUNCATE TABLE IF EXISTS REF.EMPLOYEE_PROFILES;
INSERT INTO REF.EMPLOYEE_PROFILES (PROFILE_ID, FULL_NAME, ROLE_NAME, SERVICE, HOSPITAL_ID, IS_FEATURED, META, TAGS, RISKS, KPIS, HOURS, SHIFTS, TRAINING, NEXT_BEST_ACTIONS, INSIGHTS, PEERS, CAREER)
SELECT f.value:PROFILE_ID::STRING AS PROFILE_ID,
       f.value:FULL_NAME::STRING AS FULL_NAME,
       f.value:ROLE_NAME::STRING AS ROLE_NAME,
       f.value:SERVICE::STRING AS SERVICE,
       f.value:HOSPITAL_ID::STRING AS HOSPITAL_ID,
       f.value:IS_FEATURED::BOOLEAN AS IS_FEATURED,
       f.value:META::STRING AS META,
       f.value:TAGS AS TAGS,
       f.value:RISKS AS RISKS,
       f.value:KPIS AS KPIS,
       f.value:HOURS AS HOURS,
       f.value:SHIFTS AS SHIFTS,
       f.value:TRAINING AS TRAINING,
       f.value:NEXT_BEST_ACTIONS AS NEXT_BEST_ACTIONS,
       f.value:INSIGHTS AS INSIGHTS,
       f.value:PEERS AS PEERS,
       f.value:CAREER AS CAREER
FROM TABLE(FLATTEN(INPUT => PARSE_JSON($$[{"PROFILE_ID":"joana","FULL_NAME":"Enf.ª Joana Matos","ROLE_NAME":"Enfermeiro(a)","SERVICE":"Medicina Interna","HOSPITAL_ID":"H01","IS_FEATURED":true,"META":"Enfermeira especialista · Medicina Interna · HL Lisboa · 9 anos na Luz Saúde","TAGS":[["p-teal","Contrato sem termo"],["p-ok","Especialista em reabilitação"],["p-warn","Turnos rotativos"]],"RISKS":[["Risco de saída (12 meses)",0.58,"#e4572e","3 meses seguidos com > 20 h extra; pedido de mudança de horário recusado"],["Risco de burnout",0.52,"#e4572e","6 noites nos últimos 14 dias; 2 fins de semana seguidos"],["Absentismo previsto",0.21,"#f5a800","Abaixo da média do serviço"]],"KPIS":[["Horas este mês","176 h","+22 h extra"],["Doentes por turno","7,4","serviço: 7,2"],["Avaliação de desempenho","4,6 / 5","top 10%"],["Elogios de doentes","14","no ano"]],"HOURS":{"labels":["jun","jul","ago","set","out","nov"],"base":[148,152,150,154,150,154],"extra":[12,24,21,23,26,22]},"SHIFTS":[[1,1,0,2,2,0,0],[3,3,3,0,0,1,1],[2,2,0,3,3,3,0],[0,1,1,2,3,3,3]],"TRAINING":[["Suporte Básico de Vida","Válido até 03/2027","p-ok"],["Prevenção de IACS","Expira em 12 dias","p-warn"],["Gestão de cateteres venosos","Concluído 2026","p-ok"],["Liderança de equipas","Inscrita · jan 2027","p-ml"]],"NEXT_BEST_ACTIONS":[["Aceitar o pedido de horário fixo de manhã a partir de janeiro: reduz o risco de saída para 0,31.","Propor ao enfermeiro-chefe"],["Limitar a 2 noites por semana nas próximas 4 semanas.","Ajustar escala"],["Renovar formação em Prevenção de IACS antes do fim do prazo.","Inscrever"]],"INSIGHTS":[["63% das horas extra dos últimos 3 meses foram em sextas e sábados à noite, em picos de urgência que o modelo previa com 7 dias de antecedência. Eram planeáveis com a bolsa interna.",["Escalas","Previsão de afluência"]],["Nos últimos 2 anos, 4 de 11 enfermeiros especialistas do HL Lisboa com este padrão (mais de 20 h extra durante 3 meses e um pedido recusado) saíram em menos de 6 meses.",["RH","Mod